codeExample.bad:
/* Body text at 16px (normal size): #999999 on #FFFFFF is only 2.85:1 — fails the 4.5:1 minimum */
.card-subtext {
  color: #999999;
  background-color: #FFFFFF;
  font-size: 16px;
  font-weight: normal;
}

codeExample.good:
/* Same 16px text: #595959 on #FFFFFF is 7.0:1 — comfortably passes the 4.5:1 minimum for normal text */
.card-subtext {
  color: #595959;
  background-color: #FFFFFF;
  font-size: 16px;
  font-weight: normal;
}
